package dev.aivillages.e2e.paralleld;
import java.nio.file.*;
import java.util.*;
import com.google.gson.JsonObject;
import dev.aivillages.core.kernel.logistics.*;
import dev.aivillages.fabric.logistics.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.block.Blocks;
final class DComponentMobility extends DComponentCase {
 dev.aivillages.core.kernel.storage.StorageResolver.Query query;FollowObservationAdapter follow;FollowObservationAdapter.Route following;boolean secondBudget,stopRequested,competingTested;final java.util.function.Function<UUID,ServerPlayer> players;long accepted,deadline;double allowance=128;int ownerOrdinal;String mode="";
 DComponentMobility(JsonObject s,DChestCourierScene b,Path e){this(s,b,e,id->b.level.getServer().getPlayerList().getPlayer(id));}
 DComponentMobility(JsonObject s,DChestCourierScene b,Path e,java.util.function.Function<UUID,ServerPlayer> players){super(s,b,e);this.players=players;}
 @Override void prepare(Runnable next){facts.put("destination_binding",base.destination.wire().body());if(number!=2 && number!=7)clearWall();if(number==3){base.arena.actor.setPos(origin.getX()+6.5,origin.getY(),origin.getZ()+7.5);for(int y=0;y<3;y++){for(int z=6;z<=8;z++){level.setBlockAndUpdate(origin.offset(5,y,z),Blocks.STONE.defaultBlockState());level.setBlockAndUpdate(origin.offset(7,y,z),Blocks.STONE.defaultBlockState());}for(int x=5;x<=7;x++){level.setBlockAndUpdate(origin.offset(x,y,6),Blocks.STONE.defaultBlockState());level.setBlockAndUpdate(origin.offset(x,y,8),Blocks.STONE.defaultBlockState());}}}next.run();}
 ServerPlayer principal(){return players.apply(base.scope.principal());}
 @Override void execute(ServerPlayer p){phase="MOVING";accepted=level.getGameTime();if(number<=4){mode="COME";base.arena.accept(p);facts.put("goal",base.arena.route.goal());operation("ACCEPTED",base.arena.route.observation());}else if(number==5){mode="GO_NAMED";facts.put("unsupported_landmark",MobilityPolicy.unsupportedLandmark());query=base.travelQuery(true);phase="RESOLVING_NAMED_STORAGE";facts.put("named_storage_id",base.destination.storage());facts.put("destination_binding",base.destination.wire().body());operation("RESOLUTION_STARTED",null);}else startFollow(p);}
 void startFollow(ServerPlayer p){mode="FOLLOW";deadline=level.getGameTime()+1200;follow=new FollowObservationAdapter(level,base.arena.actor,(key,tick)->new FollowObservationAdapter.Control(base.arena.identity,true,false,deadline,allowance),players);following=follow.start(DVillagerHandoffScene.id(id+"-follow-"+(++ownerOrdinal)),base.arena.identity,p);facts.put("goal",following.goal());facts.put("owner_ordinal",ownerOrdinal);facts.put("owner_travel_allowance",allowance);phase="FOLLOWING";operation("ACCEPTED",following.state());}
 void competing(){Object path=base.arena.actor.getNavigation().getPath();boolean refused=false;try{new FollowObservationAdapter(level,base.arena.actor,(key,tick)->new FollowObservationAdapter.Control(base.arena.identity,true,true,deadline,128),players).start(UUID.randomUUID(),base.arena.identity,principal());}catch(SecurityException expected){refused=true;}competingTested=true;operation("COMPETING_CONTROLLER_REFUSED",Map.of("refused",refused,"same_navigation",path==base.arena.actor.getNavigation().getPath(),"primary_path_active",!base.arena.actor.getNavigation().isDone()));}

 @Override void tick(){if(phase.equals("RESOLVING_NAMED_STORAGE")){var r=query.step();operation("RESOLUTION_STEP",Map.of("status",r.status(),"work",query.work()));if(r.status()==dev.aivillages.core.kernel.storage.StorageResolution.Status.PENDING)return;if(r.status()!=dev.aivillages.core.kernel.storage.StorageResolution.Status.RESOLVED)throw new IllegalStateException("native named resolution "+r.status());base.acceptTravel(r,true);facts.put("goal",base.route.goal());phase="MOVING";operation("ACCEPTED",base.route.observation());return;}if(terminal || phase.equals("READY") || phase.equals("PREPARING") || phase.equals("AWAIT_TRAVEL_BUDGET"))return;var p=principal();var actual=new TreeMap<String,Object>();actual.put("connected",p!=null);actual.put("native_player",p==null?null:List.of(p.getX(),p.getY(),p.getZ()));actual.put("player_dimension",p==null?null:p.level().dimension().identifier().toString());actual.put("mode",mode);long start=System.nanoTime();if(mode.equals("FOLLOW")){var s=following.step();stepNs=System.nanoTime()-start;actual.put("observation",s);facts.put("path_nodes",following.pathNodes());facts.put("path_length",following.pathLength());facts.put("diagnostic",following.diagnostic());frame("MOVE",actual);if(number==12 && !competingTested && !base.arena.actor.getNavigation().isDone())competing();if(s.terminal()){if(number==11 && !secondBudget){phase="AWAIT_TRAVEL_BUDGET";operation("TIME_EXPIRY",s);DComeScene.write(evidence.resolve("time-expired.json"),s);}else complete(s);}}
  else{var route=mode.equals("COME")?base.arena.route:base.route;var o=route.step();stepNs=System.nanoTime()-start;actual.put("observation",o);facts.put("path_nodes",route.pathNodes());facts.put("path_length",route.pathLength());facts.put("checked_chunks",route.checkedChunks());frame("MOVE",actual);if(o.terminal())complete(o);}}
 @Override void stop(ServerPlayer p){if(p==null || !p.getUUID().equals(base.scope.principal()) || following==null)throw new SecurityException("same native owner STOP");var before=base.arena.actor.getNavigation().getPath();following.cancel();stopRequested=true;facts.put("stop_tick",level.getGameTime());operation("STOP_REQUESTED",Map.of("navigation_done",base.arena.actor.getNavigation().isDone(),"prior_path_present",before!=null));}
 @Override void travelBudget(ServerPlayer p){if(number!=11 || !phase.equals("AWAIT_TRAVEL_BUDGET"))throw new IllegalStateException("explicit second bounded request");secondBudget=true;allowance=4;startFollow(p);}
}
